状态栏界面.replaceString:
```
<body>
<div id="yx-load">正在载入面板…</div>
<script>
(function(){
  var U = "https://testingcf.jsdelivr.net/gh/fkgzs123321/galgame-yingxiongtanshuo@22a49be/index.html";
  var D = document.getElementById("yx-load");
  if (typeof $ === "undefined") { if (D) D.textContent = "没载入：这个环境里没有 jQuery"; return; }
  $("body").load(U, function (r, st, xhr) {
    if (st !== "success") {
      if (D) D.textContent = "没载入：" + st + " " + (xhr ? xhr.status : "") + "　地址：" + U;
    } else if (D) { D.remove(); }
  });
})();
</script>
</body>
```

